// Command import-plan loads a plan JSON (generated by cmd/plan) into the
// database, replacing that career's plan.
package main

import (
	"encoding/json"
	"flag"
	"log"
	"os"

	"github.com/franelias/hackaton/backend/internal/db"
	"github.com/franelias/hackaton/backend/internal/plan"
)

func main() {
	faculty := flag.String("faculty", db.Faculty, "faculty the plan belongs to")
	file := flag.String("file", "data/plan_career_1.json", "plan JSON")
	flag.Parse()

	b, err := os.ReadFile(*file)
	if err != nil {
		log.Fatal(err)
	}
	var p plan.Plan
	if err := json.Unmarshal(b, &p); err != nil {
		log.Fatal(err)
	}
	g, err := db.Open(os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	if err := db.ImportPlan(g, *faculty, p); err != nil {
		log.Fatal(err)
	}
	log.Printf("imported career %d (%d subjects) for %s", p.CareerID, len(p.Subjects), *faculty)
}
